-- Rebuild Medina Book 3 lesson 9 strictly from the supplied Arabic sharh.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 39-41.
-- Source paragraph 832 prints "افتح يداك"; the private source preserves it verbatim,
-- while the public teaching example uses the grammatically required accusative "اِفْتَحْ يَدَيْكَ".
-- The two Qur'anic strings hidden by DOC control characters were transcribed literally from visible PDF page 41.

begin;
do $migration$
declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '9';
  if old_rule_count <> 3 then raise exception 'Expected 3 generated Book 3 lesson 9 rules, found %', old_rule_count; end if;

  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '9');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '9');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '9';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
  values
    ('Мединский курс (Том 3)', '9', 'الْمُثَنَّى وَعَلَامَاتُ إِعْرَابِهِ (двойственное число и признаки его падежей)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">الْمُثَنَّى</span> اسْمٌ يَدُلُّ عَلَى اثْنَيْنِ أَوِ اثْنَتَيْنِ بِزِيَادَةِ أَلِفٍ وَنُونٍ أَوْ يَاءٍ وَنُونٍ عَلَى مُفْرَدِهِ.</span><p class="rule-study-text">Двойственное число обозначает два лица или два предмета. В именительном падеже к основе добавляются алиф и нун, а в винительном и родительном — йа и нун.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Признаки падежей</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَالَةُ الْإِعْرَابِ</span><span class="rule-table-ru">падеж</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَلَامَةُ</span><span class="rule-table-ru">признак</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الرَّفْعُ</span><span class="rule-table-ru">именительный падеж</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الْأَلِفُ</span><span class="rule-table-ru">алиф</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">هَذَانِ الطَّالِبَانِ مُجْتَهِدَانِ.</span><span class="rule-table-ru">Эти два студента усердны.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">النَّصْبُ</span><span class="rule-table-ru">винительный падеж</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْيَاءُ</span><span class="rule-table-ru">йа</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ هَذَيْنِ الطَّالِبَيْنِ الْمُجْتَهِدَيْنِ.</span><span class="rule-table-ru">Я увидел этих двух усердных студентов.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْجَرُّ</span><span class="rule-table-ru">родительный падеж</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْيَاءُ</span><span class="rule-table-ru">йа</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى هَذَيْنِ الطَّالِبَيْنِ الْمُجْتَهِدَيْنِ.</span><span class="rule-table-ru">Я поприветствовал этих двух усердных студентов.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Слова, присоединяемые к двойственному числу</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُلْحَقُ بِالْمُثَنَّى</span><span class="rule-table-ru">слово, присоединяемое к двойственному</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِثَالُ الرَّفْعِ</span><span class="rule-table-ru">пример именительного падежа</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِثَالُ النَّصْبِ</span><span class="rule-table-ru">пример винительного падежа</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اثْنَانِ وَاثْنَتَانِ</span><span class="rule-table-ru">два и две</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">جَاءَ طَالِبَانِ اثْنَانِ وَطَالِبَتَانِ اثْنَتَانِ.</span><span class="rule-table-ru">Пришли два студента и две студентки.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ طَالِبَيْنِ اثْنَيْنِ وَطَالِبَتَيْنِ اثْنَتَيْنِ.</span><span class="rule-table-ru">Я увидел двух студентов и двух студенток.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِلَا وَكِلْتَا</span><span class="rule-table-ru">оба и обе</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">كِلَاهُمَا، كِلْتَاهُمَا</span><span class="rule-table-ru">оба они; обе они</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">كِلَيْهِمَا، كِلْتَيْهِمَا</span><span class="rule-table-ru">обоих; обеих</span></td></tr></tbody></table></div></div></div>', 1, 'rule', 'Двойственное число обозначает два лица или предмета; в именительном падеже его признак — алиф, а в винительном и родительном — йа.', 'الْمُثَنَّى اسْمٌ يَدُلُّ عَلَى اثْنَيْنِ أَوِ اثْنَتَيْنِ بِزِيَادَةِ أَلِفٍ وَنُونٍ أَوْ يَاءٍ وَنُونٍ عَلَى مُفْرَدِهِ. يُرْفَعُ بِالْأَلِفِ، وَيُنْصَبُ وَيُجَرُّ بِالْيَاءِ. وَيُلْحَقُ بِهِ كِلَا وَكِلْتَا وَاثْنَانِ وَاثْنَتَانِ.'),
    ('Мединский курс (Том 3)', '9', 'حَذْفُ نُونِ الْمُثَنَّى عِنْدَ الْإِضَافَةِ (удаление нуна двойственного числа при идафе)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">تُحْذَفُ <span class="ar-tone-structure">نُونُ الْمُثَنَّى</span> عِنْدَ الْإِضَافَةِ.</span><p class="rule-study-text">При присоединении второго члена идафы окончательный нун двойственного числа удаляется.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры из шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَالَةُ الْإِعْرَابِ</span><span class="rule-table-ru">падеж</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قَبْلَ الْإِضَافَةِ</span><span class="rule-table-ru">до идафы</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعَ الْإِضَافَةِ</span><span class="rule-table-ru">в идафе</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الرَّفْعُ</span><span class="rule-table-ru">именительный падеж</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">هَاتَانِ بِنْتَا حَامِدٍ.</span><span class="rule-table-ru">Эти две — дочери Хамида.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">بِنْتَانِ</span><span class="rule-table-ru">две дочери</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">بِنْتَا حَامِدٍ</span><span class="rule-table-ru">две дочери Хамида</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْجَرُّ</span><span class="rule-table-ru">родительный падеж</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى ٱبْنَيْ حَامِدٍ.</span><span class="rule-table-ru">Я поприветствовал двух сыновей Хамида.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">اِبْنَيْنِ</span><span class="rule-table-ru">двух сыновей</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">ٱبْنَيْ حَامِدٍ</span><span class="rule-table-ru">двух сыновей Хамида</span></td></tr><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الرَّفْعُ</span><span class="rule-table-ru">именительный падеж</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">جَاءَ أَلْفَا حَاجٍّ.</span><span class="rule-table-ru">Пришли две тысячи паломников.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">أَلْفَانِ</span><span class="rule-table-ru">две тысячи</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">أَلْفَا حَاجٍّ</span><span class="rule-table-ru">две тысячи паломников</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">النَّصْبُ</span><span class="rule-table-ru">винительный падеж</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اِشْتَرَيْتُ مِائَتَيْ سَاعَةٍ.</span><span class="rule-table-ru">Я купил двести часов.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مِائَتَيْنِ</span><span class="rule-table-ru">двести</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مِائَتَيْ سَاعَةٍ</span><span class="rule-table-ru">двести часов</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">النَّصْبُ</span><span class="rule-table-ru">винительный падеж</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اِفْتَحْ يَدَيْكَ.</span><span class="rule-table-ru">Открой свои руки.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَدَيْنِ</span><span class="rule-table-ru">две руки</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَدَيْكَ</span><span class="rule-table-ru">твои две руки</span></td></tr><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الرَّفْعُ</span><span class="rule-table-ru">именительный падеж</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مَاتَ أَبَوَاهُ.</span><span class="rule-table-ru">У него умерли оба родителя.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">أَبَوَانِ</span><span class="rule-table-ru">два родителя</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">أَبَوَاهُ</span><span class="rule-table-ru">оба его родителя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">النَّصْبُ</span><span class="rule-table-ru">винительный падеж</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اِغْسِلْ يَدَيْكَ.</span><span class="rule-table-ru">Вымой свои руки.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَدَيْنِ</span><span class="rule-table-ru">две руки</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَدَيْكَ</span><span class="rule-table-ru">твои две руки</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">النَّصْبُ</span><span class="rule-table-ru">винительный падеж</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">غَسَلْتُ رِجْلَيَّ.</span><span class="rule-table-ru">Я вымыл свои ноги.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رِجْلَيْنِ</span><span class="rule-table-ru">две ноги</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رِجْلَيَّ</span><span class="rule-table-ru">мои две ноги</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Исправленная форма примера</span><span class="rule-main-ar ar-tone-nasb" dir="rtl" lang="ar">اِفْتَحْ يَدَيْكَ.</span><p class="rule-study-text">После переходного повелительного глагола дополнение стоит в винительном падеже, поэтому учебная форма дана с йа двойственного числа.</p></div></div>', 2, 'rule', 'При образовании идафы нун двойственного числа удаляется; падеж продолжает выражаться алифом или йа.', 'تُحْذَفُ نُونُ الْمُثَنَّى عِنْدَ الْإِضَافَةِ، وَتَبْقَى الْأَلِفُ فِي حَالَةِ الرَّفْعِ، وَالْيَاءُ فِي حَالَتَيِ النَّصْبِ وَالْجَرِّ.'),
    ('Мединский курс (Том 3)', '9', 'كِلَا وَكِلْتَا (оба и обе)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">كِلَا وَكِلْتَا</span> اسْمَانِ لَفْظُهُمَا مُفْرَدٌ وَمَعْنَاهُمَا مُثَنًّى.</span><p class="rule-study-text">Слова «оба» и «обе» внешне имеют форму единственного числа, но обозначают двойственное число.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Согласование по форме и по смыслу</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَجْهُ الْمُرَاعَاةِ</span><span class="rule-table-ru">вид согласования</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُرَاعَاةُ اللَّفْظِ</span><span class="rule-table-ru">согласование по форме; употребляется чаще</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الطَّالِبَانِ كِلَاهُمَا مُجْتَهِدٌ.</span><span class="rule-table-ru">Оба студента усердны; сказуемое в единственном числе.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُرَاعَاةُ اللَّفْظِ</span><span class="rule-table-ru">согласование по форме; употребляется чаще</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الطَّالِبَتَانِ كِلْتَاهُمَا مُجْتَهِدَةٌ.</span><span class="rule-table-ru">Обе студентки усердны; сказуемое в единственном числе.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُرَاعَاةُ الْمَعْنَى</span><span class="rule-table-ru">согласование по двойственному смыслу; допускается</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">كِلَاهُمَا مُجْتَهِدَانِ.</span><span class="rule-table-ru">Оба они усердны; сказуемое в двойственном числе.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Падежные формы при присоединении к местоимению</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الرَّفْعُ</span><span class="rule-table-ru">именительный падеж</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّصْبُ وَالْجَرُّ</span><span class="rule-table-ru">винительный и родительный падежи</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">كِلَاهُمَا، كِلْتَاهُمَا</span><span class="rule-table-ru">оба они; обе они</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">كِلَيْهِمَا، كِلْتَيْهِمَا</span><span class="rule-table-ru">обоих; обеих</span></td></tr><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الطَّالِبَانِ كِلَاهُمَا مُجْتَهِدٌ.</span><span class="rule-table-ru">Оба студента усердны.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ كِلَيْهِمَا وَكِلْتَيْهِمَا.</span><span class="rule-table-ru">Я увидел обоих и обеих.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الطَّالِبَتَانِ كِلْتَاهُمَا مُجْتَهِدَةٌ.</span><span class="rule-table-ru">Обе студентки усердны.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى كِلَيْهِمَا وَكِلْتَيْهِمَا.</span><span class="rule-table-ru">Я поприветствовал обоих и обеих.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Условие склонения как двойственного числа</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">يُشْتَرَطُ فِي كِلَا وَكِلْتَا إِضَافَتُهُمَا إِلَى الضَّمِيرِ لِكَيْ يُعْرَبَا إِعْرَابَ الْمُثَنَّى.</span><p class="rule-study-text">Чтобы эти слова изменялись как двойственное число, они должны быть присоединены к местоимению.</p></div></div>', 3, 'rule', 'У слов «оба» и «обе» форма единственного числа, а значение двойственное; согласование чаще идёт по форме, но допускается и по смыслу.', 'كِلَا وَكِلْتَا اسْمَانِ لَفْظُهُمَا مُفْرَدٌ وَمَعْنَاهُمَا مُثَنًّى. مُرَاعَاةُ اللَّفْظِ فِيهِمَا أَكْثَرُ، وَيَجُوزُ مُرَاعَاةُ مَعْنَاهُمَا. وَيُشْتَرَطُ إِضَافَتُهُمَا إِلَى الضَّمِيرِ لِكَيْ يُعْرَبَا إِعْرَابَ الْمُثَنَّى.'),
    ('Мединский курс (Том 3)', '9', 'أَسْمَاءُ الْإِشَارَةِ لِلْمُثَنَّى (указательные имена двойственного числа)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">هَذَانِ وَهَاتَانِ</span> اسْمَا إِشَارَةٍ لِلْمُثَنَّى الْقَرِيبِ، وَ<span class="ar-tone-structure">ذَانِ وَتَانِ</span> اسْمَا إِشَارَةٍ لِلْمُثَنَّى الْبَعِيدِ.</span><p class="rule-study-text">Первые две формы указывают на близкие парные объекты, вторые две — на удалённые.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Дальние формы в трёх падежах</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَالَةُ الْإِعْرَابِ</span><span class="rule-table-ru">падеж</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُذَكَّرُ</span><span class="rule-table-ru">мужской род</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُؤَنَّثُ</span><span class="rule-table-ru">женский род</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الرَّفْعُ</span><span class="rule-table-ru">именительный падеж</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">ذَانِكَ قَلَمَانِ.</span><span class="rule-table-ru">Те две ручки.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">تَانِكَ سَيَّارَتَانِ.</span><span class="rule-table-ru">Те две машины.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">النَّصْبُ</span><span class="rule-table-ru">винительный падеж</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ ذَيْنِكَ الطَّالِبَيْنِ.</span><span class="rule-table-ru">Я увидел тех двух студентов.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ تَيْنِكَ الطَّالِبَتَيْنِ.</span><span class="rule-table-ru">Я увидел тех двух студенток.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْجَرُّ</span><span class="rule-table-ru">родительный падеж</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى ذَيْنِكَ الطَّالِبَيْنِ.</span><span class="rule-table-ru">Я поприветствовал тех двух студентов.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">سَلَّمْتُ عَلَى تَيْنِكَ الطَّالِبَتَيْنِ.</span><span class="rule-table-ru">Я поприветствовал тех двух студенток.</span></td></tr></tbody></table></div></div></div>', 4, 'rule', 'Для близких двух объектов употребляются формы «эти двое/эти две», а для удалённых — соответствующие дальние формы.', 'هَذَانِ وَهَاتَانِ اسْمَا إِشَارَةٍ لِلْمُثَنَّى الْقَرِيبِ، وَذَانِ وَتَانِ اسْمَا إِشَارَةٍ لِلْمُثَنَّى الْبَعِيدِ.'),
    ('Мединский курс (Том 3)', '9', 'إِضَافَةُ الِاسْمِ إِلَى يَاءِ الْمُتَكَلِّمِ (присоединение имени к местоимению «мой»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">إِذَا أُضِيفَ الِاسْمُ الَّذِي آخِرُهُ أَلِفٌ أَوْ يَاءٌ سَاكِنَةٌ إِلَى <span class="ar-tone-subject">يَاءِ الْمُتَكَلِّمِ</span>، فَإِنَّ يَاءَ الْمُتَكَلِّمِ تَكُونُ مَفْتُوحَةً.</span><p class="rule-study-text">При таком присоединении окончательная йа местоимения первого лица получает фатху.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Именительный падеж</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ قَبْلَ الْإِضَافَةِ</span><span class="rule-table-ru">форма до присоединения</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ مَعَ يَاءِ الْمُتَكَلِّمِ</span><span class="rule-table-ru">форма со значением «мой»</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">أَخَوَانِ</span><span class="rule-table-ru">два брата</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">أَخَوَايَ</span><span class="rule-table-ru">два моих брата</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">هَذَانِ أَخَوَايَ.</span><span class="rule-table-ru">Эти двое — мои братья.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">عَمَّانِ</span><span class="rule-table-ru">два дяди по отцу</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">عَمَّايَ</span><span class="rule-table-ru">два моих дяди по отцу</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">عَمَّايَ</span><span class="rule-table-ru">два моих дяди по отцу</span></td></tr><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">يَدَانِ</span><span class="rule-table-ru">две руки</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">يَدَايَ</span><span class="rule-table-ru">две мои руки</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">يَدَايَ</span><span class="rule-table-ru">две мои руки</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Винительный и родительный падежи</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ قَبْلَ الْإِضَافَةِ</span><span class="rule-table-ru">форма до присоединения</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ مَعَ يَاءِ الْمُتَكَلِّمِ</span><span class="rule-table-ru">форма со значением «мой»</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">أَخَوَيْنِ</span><span class="rule-table-ru">двух братьев</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">أَخَوَيَّ</span><span class="rule-table-ru">двух моих братьев</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ أَخَوَيَّ.</span><span class="rule-table-ru">Я увидел двух своих братьев.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">عَمَّيْنِ</span><span class="rule-table-ru">двух дядей по отцу</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">عَمَّيَّ</span><span class="rule-table-ru">двух моих дядей по отцу</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">عَمَّيَّ</span><span class="rule-table-ru">двух моих дядей по отцу</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَدَيْنِ</span><span class="rule-table-ru">две руки в винительном или родительном падеже</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَدَيَّ</span><span class="rule-table-ru">две мои руки</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَدَيَّ</span><span class="rule-table-ru">две мои руки</span></td></tr></tbody></table></div></div></div>', 5, 'rule', 'Если имя оканчивается на алиф или неподвижную йа и к нему присоединяется местоимение первого лица, это местоимение произносится с фатхой.', 'إِذَا أُضِيفَ الِاسْمُ الَّذِي آخِرُهُ أَلِفٌ أَوْ يَاءٌ سَاكِنَةٌ إِلَى يَاءِ الْمُتَكَلِّمِ، فَإِنَّ يَاءَ الْمُتَكَلِّمِ تَكُونُ مَفْتُوحَةً.'),
    ('Мединский курс (Том 3)', '9', 'جَمْعُ الْمُذَكَّرِ السَّالِمِ وَالْإِضَافَةُ (правильное мужское множественное число и идафа)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">جَمْعُ الْمُذَكَّرِ السَّالِمِ</span> اسْمٌ يَدُلُّ عَلَى أَكْثَرَ مِنِ اثْنَيْنِ بِزِيَادَةِ وَاوٍ وَنُونٍ أَوْ يَاءٍ وَنُونٍ عَلَى مُفْرَدِهِ.</span><p class="rule-study-text">Эта форма обозначает более двух лиц мужского рода и образуется прибавлением соответствующего окончания к единственному числу.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Признаки и примеры падежей</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَالَةُ الْإِعْرَابِ</span><span class="rule-table-ru">падеж</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَلَامَةُ</span><span class="rule-table-ru">признак</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الرَّفْعُ</span><span class="rule-table-ru">именительный падеж</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الْوَاوُ</span><span class="rule-table-ru">вау</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الْمُدَرِّسُونَ مُخْلِصُونَ.</span><span class="rule-table-ru">Преподаватели искренни.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">النَّصْبُ</span><span class="rule-table-ru">винительный падеж</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْيَاءُ</span><span class="rule-table-ru">йа</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأَيْتُ الْمُدَرِّسِينَ.</span><span class="rule-table-ru">Я увидел преподавателей.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْجَرُّ</span><span class="rule-table-ru">родительный падеж</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْيَاءُ</span><span class="rule-table-ru">йа</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">قَرَأْتُ سِيرَةَ الْمُؤْمِنِينَ.</span><span class="rule-table-ru">Я прочитал жизнеописание верующих.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْجَرُّ</span><span class="rule-table-ru">родительный падеж</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْيَاءُ</span><span class="rule-table-ru">йа</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">اِشْتَرَيْتُ الْكِتَابَ بِعِشْرِينَ رِيَالًا.</span><span class="rule-table-ru">Я купил книгу за двадцать риалов.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Удаление нуна при идафе</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قَبْلَ الْإِضَافَةِ</span><span class="rule-table-ru">до идафы</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعَ الْإِضَافَةِ</span><span class="rule-table-ru">форма без нуна</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">قَرَأْتُ مَقَالًا عَنْ مُسْلِمِي الْهِنْدِ.</span><span class="rule-table-ru">Я прочитал статью о мусульманах Индии.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مُسْلِمِينَ</span><span class="rule-table-ru">мусульман</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مُسْلِمِي الْهِنْدِ</span><span class="rule-table-ru">мусульман Индии</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَا رَأَيْتُ مُدَرِّسِي النَّحْوِ.</span><span class="rule-table-ru">Я не видел преподавателей грамматики.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مُدَرِّسِينَ</span><span class="rule-table-ru">преподавателей</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مُدَرِّسِي النَّحْوِ</span><span class="rule-table-ru">преподавателей грамматики</span></td></tr><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مُدَرِّسُو النَّحْوِ أَقْوِيَاءُ.</span><span class="rule-table-ru">Преподаватели грамматики сильны.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مُدَرِّسُونَ</span><span class="rule-table-ru">преподаватели</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مُدَرِّسُو النَّحْوِ</span><span class="rule-table-ru">преподаватели грамматики</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Удаление танвина у единственного числа</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">إِذَا كَانَ الِاسْمُ مُفْرَدًا حُذِفَ التَّنْوِينُ عِنْدَ الْإِضَافَةِ.</span><p class="rule-study-text">Если первый член идафы стоит в единственном числе, при присоединении второго члена его танвин удаляется.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры единственного числа в идафе</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُضَافُ</span><span class="rule-table-ru">первый член идафы</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَذَا كِتَابُ اللَّهِ.</span><span class="rule-table-ru">Это Книга Аллаха.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابُ</span><span class="rule-table-ru">книга; без танвина</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَيَّارَةُ خَالِدٍ جَدِيدَةٌ.</span><span class="rule-table-ru">Машина Халида новая.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَيَّارَةُ</span><span class="rule-table-ru">машина; без танвина</span></td></tr></tbody></table></div></div></div>', 6, 'rule', 'Правильное мужское множественное число поднимается посредством вау, а в винительном и родительном падежах имеет йа; при идафе его нун удаляется.', 'جَمْعُ الْمُذَكَّرِ السَّالِمِ اسْمٌ يَدُلُّ عَلَى أَكْثَرَ مِنِ اثْنَيْنِ بِزِيَادَةِ وَاوٍ وَنُونٍ أَوْ يَاءٍ وَنُونٍ عَلَى مُفْرَدِهِ. يُرْفَعُ بِالْوَاوِ، وَيُنْصَبُ وَيُجَرُّ بِالْيَاءِ. وَتُحْذَفُ نُونُهُ عِنْدَ الْإِضَافَةِ، كَمَا يُحْذَفُ تَنْوِينُ الِاسْمِ الْمُفْرَدِ عِنْدَ الْإِضَافَةِ.'),
    ('Мединский курс (Том 3)', '9', 'صَوْغُ الْأَمْرِ مِنَ الْفِعْلِ أَتَى (образование повелительной формы от глагола «приходить»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-verb">أَتَى</span> فِعْلٌ مَاضٍ، وَمُضَارِعُهُ <span class="ar-tone-verb">يَأْتِي</span>، وَالْأَمْرُ مِنْهُ <span class="ar-tone-verb">اِيتِ</span>.</span><p class="rule-study-text">Шарх даёт прошедшую, настояще-будущую и повелительную формы глагола «приходить».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Образование формы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее время</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущее время</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَصْلُ الْأَمْرِ</span><span class="rule-table-ru">исходная повелительная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْرُ بَعْدَ الْإِبْدَالِ</span><span class="rule-table-ru">форма после замены</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَتَى</span><span class="rule-table-ru">он пришёл</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَأْتِي</span><span class="rule-table-ru">он приходит</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِئْتِ</span><span class="rule-table-ru">исходная форма «приди»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِيتِ</span><span class="rule-table-ru">«приди» после замены второй хамзы на йа</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Причина замены</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">أُبْدِلَتِ الْهَمْزَةُ الثَّانِيَةُ يَاءً لِمُنَاسَبَةِ الْكَسْرَةِ الَّتِي قَبْلَهَا.</span><p class="rule-study-text">Вторая хамза заменяется на йа в соответствии с предшествующей касрой.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Обычные примеры</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِيتِ بِالْكِتَابِ يَا مُحَمَّدُ.</span><span class="rule-table-ru">Принеси книгу, Мухаммад.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِيتِ</span><span class="rule-table-ru">приди; принеси</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِيتِنِي بِالْكِتَابِ.</span><span class="rule-table-ru">Принеси мне книгу.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِيتِنِي</span><span class="rule-table-ru">принеси мне</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">После вау или фа</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">إِذَا سُبِقَ فِعْلُ الْأَمْرِ بِالْوَاوِ أَوِ الْفَاءِ، حُذِفَتِ الْهَمْزَةُ الْأُولَى وَلَمْ تُحْذَفِ الْهَمْزَةُ الثَّانِيَةُ.</span><p class="rule-study-text">После соединительного вау или фа начальная хамза отпадает, а корневая хамза сохраняется.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры из шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">﴿ فَأْتِ بِهَا مِنَ الْمَغْرِبِ ﴾</span><span class="rule-table-ru">«Тогда приведи его с запада»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَأْتِ</span><span class="rule-table-ru">фа + «приди/приведи»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">﴿ وَأْتُوا الْبُيُوتَ مِنْ أَبْوَابِهَا ﴾</span><span class="rule-table-ru">«И входите в дома через их двери»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَأْتُوا</span><span class="rule-table-ru">вау + «приходите/входите»</span></td></tr></tbody></table></div></div></div>', 7, 'rule', 'Шарх выводит повелительную форму глагола «приходить» из исходной формы с двумя хамзами и отдельно показывает её написание после вау и фа.', 'الْفِعْلُ أَتَى فِعْلٌ مَاضٍ، وَمُضَارِعُهُ يَأْتِي، وَالْأَمْرُ مِنْهُ اِيتِ. أَصْلُهُ اِئْتِ، فَأُبْدِلَتِ الْهَمْزَةُ الثَّانِيَةُ يَاءً لِمُنَاسَبَةِ الْكَسْرَةِ قَبْلَهَا. وَإِذَا سُبِقَ فِعْلُ الْأَمْرِ بِالْوَاوِ أَوِ الْفَاءِ حُذِفَتِ الْهَمْزَةُ الْأُولَى وَلَمْ تُحْذَفِ الثَّانِيَةُ.');

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'الدَّرْسُ التَّاسِعُ
الْمُثَنَّى
المثنَّى ، هو : الاسمُ الذي يَدُلُّ على اثْنَيْنِ ، أو اثْنَتَيْنِ بزيادةِ أَلفٍ ونُونٍ على مُفْرَدِه .
عَلاَمَاتُهُ : يُرْفَعُ بالألف ، ويُنْصَبُ ويُجَرُّ بالياء .
الْمُلْحَقُ به : كِلاَ وكِلْتَا ، واثْنَانِ واثْنَتَانِ .
الأمثلة :
هذانِ الطَّالِبانِ مجتهدان .                رأيت هذينِ الطَّالِبَيْنِ المجتَهدَيْنِ .
سلَّمت على هذين الطَّالبينِ المجتهدينِ .
جاء طالبان اثنان وطالبتان اثنتان        رأيت طالبينِ اثنين وطالبتين اثنتين .', 39, 39, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '9' and sort_order = 1;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', '* تُحذفُ نُونُ المثنَّى عندَ الإضافةِ ، نحو :
هاتان بنتا حامدٍ . سلّمت على ابْنَيْ حامدٍ . جاء أَلْفَا حاجًّ . اشتريتُ مِائَتَيْ سَاعَةٍ .
افتحْ يَدَاك . مات أَبَوَاهُ . اغسلْ يَدَيْكَ . غسلتُ رِجْلَيَّ .', 39, 39, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '9' and sort_order = 2;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'الطالبان كلاهما مجتهدٌ .                 الطالبتان كلتاهما مجتهدةٌ .
رأيت كليهما وكلتيهما                سلّمت على كليهما وكلتيهما .
* كِلاَ ، وكِلْتَا : اسمان لفظهما مُفرد ومَعْنَاهُما مُثنّى ، ومُراعاة اللفظ فيهما أكثر ، نحو :  كلاهما مجتهد ، ويجوز مراعاة معناهما ، نحو : كلاهما مجتهدان .
* يُشْترط في كِلاَ وكِلْتا إضافتهما إلى الضمير لكي يُعْرَبَانِ إعرابَ المثنى :كلاهما، وكلتاهما.', 39, 40, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '9' and sort_order = 3;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'ذَانِكَ قَلمانِ                             تَانِك سَيَّارتانِ .
رأيت ذَيْنِك الطَّالبينِ                    رأيت تَيْنِكَ الطَّالبتينِ .
سَلَّمت على ذَيْنِكَ الطَّالبينِ             سلّمت على تَيْنِكَ الطَّالبتينِِ .
